\"\"\"Restore the pristine exam, including collection and reporting configuration.\"\"\"
from __future__ import annotations

import os
import shutil
import subprocess
from pathlib import Path


def git(repo: Path, *args: str) -> subprocess.CompletedProcess:
    env = dict(os.environ, GIT_CONFIG_GLOBAL='/dev/null', GIT_CONFIG_NOSYSTEM='1')
    return subprocess.run(['git', '-c', 'safe.directory=*', *args], cwd=repo,
                          env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                          text=True, check=True)


def protected(path: str, required_files=()) -> bool:
    p = Path(path)
    return (path in required_files or any(part in ('test', 'tests', 'testing') for part in p.parts)
            or p.name.startswith('test_') or p.name.endswith('_test.py')
            or p.name in ('tests.py', 'conftest.py', 'pytest.ini', '.pytest.ini',
                          'pyproject.toml', 'setup.cfg', 'tox.ini', 'setup.py'))


def restore_tests(repo_root: Path, required_files=()) -> list[str]:
    # HEAD, not the patched filesystem, inventories deleted and renamed tests too.
    tracked = set(git(repo_root, 'ls-tree', '-rz', '--name-only', 'HEAD').stdout.rstrip('\\0').split('\\0'))
    current = {str(p.relative_to(repo_root)) for p in repo_root.rglob('*')
               if '.git' not in p.relative_to(repo_root).parts and (p.is_file() or p.is_symlink())}
    restored = []
    for name in sorted(tracked | current):
        if not name or not protected(name, required_files):
            continue
        p = repo_root / name
        if p.is_symlink() or p.is_file():
            p.unlink()
        elif p.is_dir():
            shutil.rmtree(p)
        if name in tracked:
            # Remove symlink ancestors introduced by a rollout before checking out.
            for parent in reversed(p.parents):
                if parent == repo_root or repo_root not in parent.parents:
                    continue
                if parent.is_symlink():
                    parent.unlink()
            git(repo_root, 'checkout', 'HEAD', '--', name)
        restored.append(name)
    return restored
PY
